import re

with open('references.bib', 'r') as f:
    content = f.read()

# Search for key papers
search_terms = [
    'Shumailov',  # Model collapse
    'Mitchell',   # DetectGPT
    'Hans',       # Binoculars
    'Schaeffer',  # Model collapse definitions
]

found = {}
for term in search_terms:
    matches = re.findall(rf'{term}[^}}]*?author\s*=\s*\{{(.+?)\}}[^}}]*?(?:year|booktitle)[^}}]*?year\s*=\s*\{{(\d{{4}})}}', content, re.DOTALL | re.IGNORECASE)
    found[term] = matches

for term, matches in found.items():
    print(f"\nSearching for '{term}':")
    if matches:
        for author_block, year in matches:
            print(f"  Found (year {year}): {author_block[:100]}")
    else:
        print(f"  NOT FOUND")

# Check for specific known keys
print("\n\nChecking specific seminal papers:")
seminal = ['curse_of_recursion', 'self_consuming_mad', 'dohmatob_tale_of_tails', 'schaeffer_collapse_position']
for key in seminal:
    if re.search(rf'{key}', content):
        print(f"  {key}: PRESENT")
    else:
        print(f"  {key}: MISSING")

EOF

